-- Datos de ejemplo para desarrollo y demo. Se puede aplicar más de una vez.
--   docker exec -i logistics-postgres psql -U logistics -d logistics < db/seed.sql
-- Los ids son fijos para poder referenciarlos desde el frontend y los ejemplos.

-- Cuatro sucursales en las esquinas de un cuadrado de unos 4,4 km de lado en Bahía Blanca.
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

-- Stock repartido a propósito para que la elección de sucursal tenga competencia:
--   la leche solo está en las del sur, el azúcar solo en Noreste y Sureste, el aceite está
--   agotado en Suroeste, los fideos en Noreste y la harina del Noroeste casi se acaba (2 unidades).
ON CONFLICT (branch_id, product_id) DO NOTHING;

-- Todos los usuarios de prueba tienen la contraseña demo1234 (guardada con scrypt, nunca en claro).
-- Hay dos repartidores por sucursal: 1 y 5 en Noroeste, 2 y 6 en Noreste, 3 y 7 en Suroeste, 4 y 8 en Sureste.
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;
